import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Module: fragments","description":"","frontmatter":{},"headers":[],"relativePath":"api/kernel/handl_language/fragments.md","filePath":"api/kernel/handl_language/fragments.md"}`),a={name:`api/kernel/handl_language/fragments.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><strong>handl_language &gt; fragments</strong></p><h1 id="module-fragments" tabindex="-1">Module: fragments <a class="header-anchor" href="#module-fragments" aria-label="Permalink to “Module: fragments”">​</a></h1><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p><strong>Modules</strong></p><ul><li><a href="#ast-shape"><code>ast_shape</code></a> - AST shape fragment definitions.</li><li><a href="#capability"><code>capability</code></a> - Capability declaration fragment definitions.</li><li><a href="#eval-scheme"><code>eval_scheme</code></a> - Eval scheme fragment definitions (arrow-calculus kernel, ADR-0052).</li><li><a href="#grammar"><code>grammar</code></a> - Grammar row fragment definitions.</li><li><a href="#lexer-rule"><code>lexer_rule</code></a> - Lexer rule fragment definitions.</li><li><a href="#lint-rule"><code>lint_rule</code></a> - Lint rule fragment definitions (ADR-0097 — Lint Rules as Language Data).</li><li><a href="#lsp"><code>lsp</code></a> - LSP surface fragment definitions (ADR-0100).</li><li><a href="#option"><code>option</code></a> - Option schema fragment definitions.</li><li><a href="#token-kind"><code>token_kind</code></a> - Token kind fragment definitions.</li><li><a href="#transform-def"><code>transform_def</code></a> - Transform rule fragment definitions (ADR-0094 — Generic AST Transform</li><li><a href="#type-rule"><code>type_rule</code></a> - Type rule fragment definitions (ADR-0054 — Generic Typecheck Engine).</li></ul><hr><h2 id="module-ast-shape" tabindex="-1">Module: ast_shape <a class="header-anchor" href="#module-ast-shape" aria-label="Permalink to “Module: ast_shape”">​</a></h2><p>AST shape fragment definitions. AST shape fragment definitions.</p><h2 id="module-capability" tabindex="-1">Module: capability <a class="header-anchor" href="#module-capability" aria-label="Permalink to “Module: capability”">​</a></h2><p>Capability declaration fragment definitions. Capability declaration fragment definitions.</p><h2 id="module-eval-scheme" tabindex="-1">Module: eval_scheme <a class="header-anchor" href="#module-eval-scheme" aria-label="Permalink to “Module: eval_scheme”">​</a></h2><p>Eval scheme fragment definitions (arrow-calculus kernel, ADR-0052). Eval scheme fragment definitions (arrow-calculus kernel, ADR-0052).</p><h2 id="module-grammar" tabindex="-1">Module: grammar <a class="header-anchor" href="#module-grammar" aria-label="Permalink to “Module: grammar”">​</a></h2><p>Grammar row fragment definitions. Grammar row fragment definitions.</p><h2 id="module-lexer-rule" tabindex="-1">Module: lexer_rule <a class="header-anchor" href="#module-lexer-rule" aria-label="Permalink to “Module: lexer_rule”">​</a></h2><p>Lexer rule fragment definitions. Lexer rule fragment definitions.</p><p>A [<code>LexerRuleDef</code>] carries the <em>pattern</em> data a data-driven lexer engine uses to recognize one token kind in source text (ADR-0044 §1). Like token kinds and AST shapes, lexer rules are <strong>structural facts</strong> (&quot;this is how you recognize a <code>token.number</code>&quot;), so they merge with <strong>union (idempotent)</strong> semantics — re-declaring the same rule id is a no-op (first wins).</p><p>The identity key is the rule <code>id</code> (not <code>token_kind</code>), so multiple rules can produce the same token kind (e.g. <code>lex.bool.true</code> and <code>lex.bool.false</code> both produce <code>token.bool</code>).</p><h2 id="module-lint-rule" tabindex="-1">Module: lint_rule <a class="header-anchor" href="#module-lint-rule" aria-label="Permalink to “Module: lint_rule”">​</a></h2><p>Lint rule fragment definitions (ADR-0097 — Lint Rules as Language Data). Lint rule fragment definitions (ADR-0097 — Lint Rules as Language Data).</p><p>A <em>lint rule</em> maps a check over source or AST to a diagnostic. Rules live in the <a href="crate::Language" target="_blank" rel="noreferrer"><code>Language</code></a> <code>lints</code> fragment set — adding a rule to a language is a data change, never an engine recompile.</p><p>This crate holds only the <strong>data</strong>: [<code>LintCheck</code>] and [<code>LintFix</code>] are the rule <em>vocabulary</em> — they are interpreted by lint engines (e.g. <code>hnl-engine-lint</code>), never executed here. The <code>Native</code> check variant is the disciplined escape hatch (same pattern as <a href="crate::TransformRule::Native" target="_blank" rel="noreferrer"><code>TransformRule::Native</code></a>): dispatch stays in <code>LintRuleDef</code> data while the implementation — scope analysis, whole-source checks, host-tool composition — is supplied by a native-lint registry.</p><h1 id="serde-representation" tabindex="-1">Serde representation <a class="header-anchor" href="#serde-representation" aria-label="Permalink to “Serde representation”">​</a></h1><p>All enums use serde&#39;s default <strong>externally tagged</strong> representation, matching <a href="crate::TransformRule" target="_blank" rel="noreferrer"><code>TransformRule</code></a> and friends: a check is <code>{&quot;Match&quot;: {&quot;node_kind&quot;: …, &quot;when&quot;: …}}</code> or <code>{&quot;Native&quot;: &quot;scope.unbound-wire&quot;}</code>.</p><h2 id="module-lsp" tabindex="-1">Module: lsp <a class="header-anchor" href="#module-lsp" aria-label="Permalink to “Module: lsp”">​</a></h2><p>LSP surface fragment definitions (ADR-0100). LSP surface fragment (ADR-0100).</p><p>A <code>LspDef</code> is a generic, method-keyed declaration of which LSP requests a language supports and which data-driven rules the <code>plugin-lsp</code> engine should run for each. The engine is method-agnostic: it looks at the LSP method string, evaluates the rule list in order, and dispatches each rule by its <code>kind</code> field. All rule configuration lives in the <code>config</code> map, so a language can invent rules for any future <code>kind</code> the engine learns without changing the <code>Language</code> schema.</p><h2 id="module-option" tabindex="-1">Module: option <a class="header-anchor" href="#module-option" aria-label="Permalink to “Module: option”">​</a></h2><p>Option schema fragment definitions. Option schema fragment definitions.</p><p><code>OptionSchema</code> is defined locally here rather than re-exported from <code>handl-platform</code>. The platform&#39;s <code>OptionSchema</code> is not <code>serde</code>-serializable (its <code>OptionScope</code> enum lacks serde derives and it is coupled to the <code>Plugin</code>/<code>RuleAcceptor</code> runtime machinery), so reusing it would either break serialization of <code>Language</code> or pull in plugin-system coupling. This minimal data-only version keeps <code>Language</code> serializable end to end while preserving the same <code>id</code>-keyed identity semantics.</p><h2 id="module-token-kind" tabindex="-1">Module: token_kind <a class="header-anchor" href="#module-token-kind" aria-label="Permalink to “Module: token_kind”">​</a></h2><p>Token kind fragment definitions. Token kind fragment definitions.</p><h2 id="module-transform-def" tabindex="-1">Module: transform_def <a class="header-anchor" href="#module-transform-def" aria-label="Permalink to “Module: transform_def”">​</a></h2><p>Transform rule fragment definitions (ADR-0094 — Generic AST Transform Engine). Transform rule fragment definitions (ADR-0094 — Generic AST Transform Engine).</p><p>A <em>transform</em> is a pure <code>Ast → Ast</code> rewrite: it never evaluates, typechecks, or emits. A <em>pass</em> is a named, ordered set of transform rules (e.g. <code>desugar</code>, <code>lower</code>, <code>optimize</code>). A [<code>TransformDef</code>] maps a node kind to a rewrite within a pass; the <a href="crate::Language" target="_blank" rel="noreferrer"><code>Language</code></a> <code>transforms</code> fragment set is the dispatch table a transform engine reads.</p><p>This crate holds only the <strong>data</strong>: [<code>TransformRule</code>], [<code>RewriteStep</code>], and [<code>TransformCondition</code>] are the rewrite <em>vocabulary</em> — they are interpreted by transform engines (e.g. <code>hnl-engine-transform-rewrite</code>), never executed here. The <code>Native</code> rule variant and the <code>Splice</code>/<code>Apply</code>/<code>PayloadEq</code> vocabulary are declared now so the schema is complete; they need no runtime support in this crate.</p><h1 id="serde-representation-1" tabindex="-1">Serde representation <a class="header-anchor" href="#serde-representation-1" aria-label="Permalink to “Serde representation”">​</a></h1><p>All enums use serde&#39;s default <strong>externally tagged</strong> representation — matching every other enum in this crate (<code>AstDesugarChild</code>, <code>LexerPattern</code>, …). A rule is <code>{&quot;Declarative&quot;: {&quot;target_kind&quot;: …, &quot;children&quot;: […]}}</code> or <code>{&quot;Native&quot;: &quot;desugar.while&quot;}</code>; a step is <code>{&quot;Keep&quot;: 0}</code> / <code>{&quot;KeepRole&quot;: &quot;target&quot;}</code> / <code>{&quot;Create&quot;: {…}}</code>; a condition is <code>{&quot;KindAt&quot;: {…}}</code> / <code>{&quot;And&quot;: […]}</code> / etc. JSON and YAML round-trip identically.</p><h2 id="module-type-rule" tabindex="-1">Module: type_rule <a class="header-anchor" href="#module-type-rule" aria-label="Permalink to “Module: type_rule”">​</a></h2><p>Type rule fragment definitions (ADR-0054 — Generic Typecheck Engine). Type rule fragment definitions (ADR-0054 — Generic Typecheck Engine).</p>`,40)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};